//! Re-exports C++ bindings generated by rs_bindings_from_cc, including the
//! free functions that rs_bindings_from_cc generates for C++ methods.

pub use ::cc_type::cc_ns::cc_type::*;
pub use ::cc_type::cc_ns::CcType;

pub fn make_value(value: i32) -> ::cc_type::cc_ns::CcType {
    ::cc_type::cc_ns::CcType { value }
}

/// Calls the free function that rs_bindings_from_cc generates for
/// `CcType::GetValue`, to check that it is usable from other crates.
pub fn get_value_via_free_fn(value: &::cc_type::cc_ns::CcType) -> i32 {
    ::cc_type::cc_ns::cc_type::GetValue(value)
}
